//! Derived reader/article fields. These never rewrite an immutable lesson packet.
use crate::backend::{
    rendering::{highlight_code, render_markdown, MarkdownOptions},
    unicode::{lowercase, python_space, splitlines},
    Result,
};
use serde_json::{json, Value};

/// `read_key` is generated by the host for this response, never saved by a GET.
pub fn present_note(lesson: &Value, read_key: &str) -> Result<Value> {
    let mut lesson = lesson.clone();
    lesson["read_key"] = read_key.into();
    let article = lesson.get("article").cloned();
    let references: Vec<_> = if let Some(article) = &article {
        article["source_ids"]
            .as_array()
            .cloned()
            .unwrap_or_default()
    } else {
        lesson["sources"]
            .as_array()
            .into_iter()
            .flatten()
            .map(|source| source["id"].clone())
            .collect()
    };
    let official: Vec<_> = lesson["sources"]
        .as_array()
        .into_iter()
        .flatten()
        .filter(|source| source["kind"] == "official" && references.contains(&source["id"]))
        .enumerate()
        .map(|(index, source)| {
            let mut source = source.clone();
            source["number"] = json!(index + 1);
            source
        })
        .collect();
    lesson["article_references"] = json!(official);
    if let Some(article) = &article {
        lesson["article_intro"] = render_markdown(
            article["intro"].as_str().unwrap_or(""),
            &MarkdownOptions::default(),
        )
        .html
        .into();
        lesson["article_takeaway"] = render_markdown(
            article["takeaway"].as_str().unwrap_or(""),
            &MarkdownOptions::default(),
        )
        .html
        .into();
        lesson["article_sections"] = json!(article["sections"]
            .as_array()
            .into_iter()
            .flatten()
            .map(|section| {
                let mut section = section.clone();
                section["html"] = render_markdown(
                    section["body"].as_str().unwrap_or(""),
                    &MarkdownOptions::default(),
                )
                .html
                .into();
                section["references"] = json!(official
                    .iter()
                    .filter(|source| section["source_ids"]
                        .as_array()
                        .is_some_and(|ids| ids.contains(&source["id"])))
                    .cloned()
                    .collect::<Vec<_>>());
                section
            })
            .collect::<Vec<_>>());
    }
    if let Some(scene) = lesson.get("scene").cloned() {
        let lines = splitlines(scene["code"].as_str().unwrap_or(""));
        let (start, end) = if let Some(article) = &article {
            (
                article["code_range"][0].as_u64().unwrap_or(1) as usize,
                article["code_range"][1].as_u64().unwrap_or(0) as usize,
            )
        } else {
            (1, 6.min(lines.len()))
        };
        lesson["preview_start"] = json!(start);
        lesson["preview_end"] = json!(end);
        lesson["preview_partial"] = json!(start > 1 || end < lines.len());
        lesson["code_numbers"] = (start..=end)
            .map(|number| number.to_string())
            .collect::<Vec<_>>()
            .join("\n")
            .into();
        let labels = lowercase(scene["language"].as_str().unwrap_or(""));
        let language = if scene["kind"] == "diff" {
            "diff"
        } else {
            labels
                .split(|ch| python_space(ch) || ch == '/')
                .find(|label| matches!(*label, "bash" | "sh" | "shell" | "zsh" | "console"))
                .unwrap_or("text")
        };
        let code = if start > 0 && start <= end && end <= lines.len() {
            lines[start - 1..end].join("\n")
        } else {
            String::new()
        };
        lesson["code_preview_html"] = highlight_code(&code, language).into();
    }
    Ok(lesson)
}
